function rowsOfTree(root: TreeNode | null): number[][] {
  const rows: number[][] = [];
  let level: TreeNode[] = root ? [root] : [];
  while (level.length) {
    rows.push(level.map(n => n.val));
    const next: TreeNode[] = [];
    for (const n of level) {
      if (n.left) next.push(n.left);
      if (n.right) next.push(n.right);
    }
    level = next;
  }
  return rows;
}

