function rowsOfTree(root: TreeNode | null): number[][] {
  const rows: number[][] = [];
  const walk = (n: TreeNode | null, depth: number): void => {
    if (!n) return;
    if (rows.length === depth) rows.push([]); // first visit to this level
    rows[depth].push(n.val);
    walk(n.left, depth + 1);
    walk(n.right, depth + 1);
  };
  walk(root, 0);
  return rows;
}

